insert into public.sentences (text, text_zh, notebook_id) values ('Success is becoming in middle adulthood what you dreamed to be in late childhood. The rest comes from loss of control.', '成功是在中年成为你童年末期梦想成为的人。其余的都是失控造成的。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('The opposite of success isn''t failure; it is namedropping.', '成功的反面不是失败，而是炫耀名号。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Modernity needs to understand that being rich and becoming rich are not mathematically, personally, socially, and ethically the same thing.', '现代社会需要明白，拥有财富和变得富有在数学上、个人上、社会上和伦理上都不相同。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('You don''t become completely free by just avoiding to be a slave; you also need to avoid becoming a master.', '仅仅避免成为奴隶并不能让你完全自由，你还需要避免成为主人。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Fortune punishes the greedy by making him poor and the very greedy by making him rich.', '财富惩罚贪婪者，让他贫穷；而极度贪婪者则会变得富有。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Quite revealing of human preferences that more suicides come from shame or loss of financial and social status than medical diagnoses.', '令人深思的是，自杀更多源于羞耻或失去经济和社会地位，而非医疗诊断。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('"Wealthy" is meaningless and has no robust absolute measure; use intead the subtractive measure "unwealth," that is, the difference, at any point in time, between what you have and what you would like to have.', '“富有”一词毫无意义，也没有绝对的衡量标准；应使用“非富有”这个减法概念，即你拥有的与想要拥有的之间的差距。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Older people are most beautiful when they have what is lacking in the young: poise, erudition, wisdom, phronesis, and this postheroic absence of agitation.', '年长者最美丽之处在于他们拥有年轻人所缺乏的：沉着、博学、智慧、实践智慧，以及这种超越英雄时代的宁静。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('I went to a happiness conference; researchers looked very unhappy.', '我参加了一个幸福会议；研究人员看起来非常不快乐。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('What fools call "wasting time" is most often the best investment.', '愚人所称的“浪费时间”，往往是最好的投资。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Decline starts with the replacement of dreams with memories and ends with the replacement of memories with other memories.', '衰退始于梦想被回忆取代，终于回忆被其他回忆取代。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('You want to avoid being disliked without being envied or admired.', '你想避免被讨厌，同时也不想被羡慕或崇拜。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Read nothing from the past one hundred years; eat no fruits from the past one thousand years; drink nothing from the past four thousand years (just wine and water); but talk to no ordinary man over forty. A man without a heroic bent starts dying at the age of thirty.', '不要阅读过去一百年的书；不要吃过去一千年的果实；不要喝过去四千年的饮料（只喝酒和水）；但不要与四十岁以上的普通人交谈。没有英雄气概的人三十岁就开始死去。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Some pursuits are much duller from the inside. Even piracy, they say.', '有些追求从内部看起来非常乏味。甚至海盗也是如此，据说。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Karl Marx, a visionary, figured out that you can control a slave much better by convincing him he is an employee.', '远见卓识的卡尔·马克思发现，说服奴隶他是雇员，可以更好地控制他。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Catholic countries had more serial monogamy than today, but without the need for divorcelife expectancy was short; marriage duration was much, much shorter.', '天主教国家的连续一夫一妻制比今天更多，但没有离婚的需求，寿命较短；婚姻持续时间也短得多。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('The fastest way to become rich is to socialize with the poor; the fastest way to become poor is to socialize with the rich.', '最快致富的方法是与穷人交往；最快变穷的方法是与富人交往。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('You will be civilized on the day you can spend a long period doing nothing, learning nothing, and improving nothing, without feeling the slightest amount of guilt.', '当你能长时间无所事事、不学习、不进步而不感到丝毫内疚时，你才算文明。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Someone who says "I am busy" is either declaring incompetence (and lack of control of his life) or trying to get rid of you.', '说“我很忙”的人，要么是在宣告无能（和对生活的失控），要么是在试图摆脱你。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('The difference between slaves in Roman and Ottoman days and today''s employees is that slaves did not need to flatter their boss.', '罗马和奥斯曼时代的奴隶与今天的雇员的区别在于奴隶不需要奉承他们的老板。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('You are rich if and only if money you refuse tastes better than money you accept.', '只有当你拒绝的钱比你接受的钱更让你满意时，你才算富有。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('For most, success is the harmful passage from the camp of the hating to the camp of the hated.', '对大多数人来说，成功是从仇恨者阵营到被仇恨者阵营的有害转变。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('To see if you like where you are, without the chains of dependence, check if you are as happy returning as you were leaving.', '想知道你是否喜欢现在的地方，且没有依赖的束缚，看看你回来的时候是否和离开时一样快乐。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('The difference between love and happiness is that those who talk about love tend to be in love, but those who talk about happiness tend to be not happy.', '爱与幸福的区别在于，谈论爱的人往往正处于爱情中，而谈论幸福的人往往并不幸福。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Modernity: we created youth without heroism, age without wisdom, and life without grandeur.', '现代性：我们创造了没有英雄气概的青春、没有智慧的老年和没有壮丽的人生。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('You can tell how uninteresting a person is by asking him whom he finds interesting.', '你可以通过问一个人他觉得谁有趣，来判断他有多无趣。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('The Web is an unhealthy place for someone hungry for attention.', '对于渴望关注的人来说，网络是一个不健康的地方。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('I wonder if anyone ever measured the time it takes, at a party, before a mildly successful stranger who went to Harvard makes others aware of it.', '我想知道有没有人测量过，在聚会上，一个稍有成就的哈佛陌生人让别人知道这件事需要多长时间。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('People focus on role models; it is more effective to find antimodelspeople you don''t want to resemble when you grow up.', '人们关注榜样；但找到反面典型——那些你长大后不想像的人——更有效。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('It is a good practice to always apologize, except when you have done something wrong.', '总是道歉是个好习惯，除非你确实做错了事。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Preoccupation with efficacy is the main obstacle to a poetic, noble, elegant, robust, and heroic life.', '过分关注效率是过上诗意、高贵、优雅、坚韧和英雄般生活的主要障碍。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Some, like most bankers, are so unfit for success that they look like dwarves dressed in giants'' clothes.', '有些人，比如大多数银行家，极不适合成功，看起来就像穿着巨人衣服的小矮人。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Don''t complain too loud about wrongs done you; you may give ideas to your less imaginative enemies.', '不要大声抱怨别人对你的不公；你可能会给缺乏想象力的敌人提供灵感。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Most feed their obsessions by trying to get rid of them.', '大多数人通过试图摆脱执念来滋养它们。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('It is as difficult to change someone''s opinions as it is to change his tastes.', '改变一个人的观点和改变他的品味一样难。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('I have the fondest memories of time spent in places called ugly, the most boring ones of places called scenic.', '我对那些被称为“丑陋”的地方度过的时光记忆最深刻，对那些被称为“风景优美”的地方则觉得最无聊。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Fitness is certainly the sign of strength, but outside of natural stimuli the drive to acquire =tness can signal some deep incurable weakness.', '健身无疑是力量的象征，但在非自然刺激下，追求健身的动力可能反映某种深层无法治愈的弱点。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Charm is the ability to insult people without offending them; nerdiness the reverse.', '魅力是能在不冒犯别人的情况下讽刺他们；书呆子气则相反。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Those who do not think that employment is systemic slavery are either blind or employed.', '不认为就业是系统性奴役的人，要么是盲目，要么就是被雇佣者。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('They are born, then put in a box; they go home to live in a box; they study by ticking boxes; they go to what is called "work" in a box, where they sit in their cubicle box; they drive to the grocery store in a box to buy food in a box; they go to the gym in a box to sit in a box; they talk about thinking "outside the box"; and when they die they are put in a box. All boxes, Euclidian, geometrically smooth boxes.', '他们出生后被放进盒子；回家住在盒子里；学习时打勾盒子；去所谓的“工作”也是在盒子里，坐在隔间盒子里；开车去杂货店买盒子里的食物；去健身房坐在盒子里；谈论“跳出盒子思考”；死后也被放进盒子。所有盒子，欧几里得的，几何光滑的盒子。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Another definition of modernity: conversations can be more and more completely reconstructed with clips from other conversations taking place at the same time on the planet.', '现代性的另一种定义是：对话可以越来越多地被同时发生在地球上其他对话的片段完全重构。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('The twentieth century was the bankruptcy of the social utopia; the twentyfirst will be that of the technological one.', '二十世纪是社会乌托邦的破产；二十一世纪将是技术乌托邦的破产。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('Efforts at building social, political, and medical utopias have caused nightmares; many cures and techniques came from martial efforts.', '构建社会、政治和医疗乌托邦的努力导致了噩梦；许多疗法和技术源于军事努力。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('The Web''s "connectedness" creates a peculiar form of informational and pseudosocial promiscuity, which makes one feel clean after Web rationing.', '网络的“连通性”创造了一种特殊的信息和伪社交的泛滥，使人在网络限量后感到清净。', 26);
insert into public.sentences (text, text_zh, notebook_id) values ('In most debates, people seem to be trying to convince one another; but all they can hope for is new arguments to convince themselves.', '在大多数辩论中，人们似乎试图说服对方；但他们唯一能期望的是获得新的论据来说服自己。', 26);